import { MeshBasicNodeMaterial, PlaneGeometry, LineBasicMaterial, EdgesGeometry, Line, Group, Color } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { paper, accent } = config.colors || {};
  const paperColor = new Color(paper);
  const accentColor = new Color(accent);

  const group = new Group();

  // Texture loading
  let texture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      if (cardMaterial) {
        cardMaterial.map = tex;
        cardMaterial.needsUpdate = true;
      }
    });
  }

  // Card plane
  const cardGeometry = new PlaneGeometry(2, 1.25);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: paperColor,
    roughness: 0.6,
    metalness: 0.1
  });
  const cardMesh = new Mesh(cardGeometry, cardMaterial);
  cardMesh.position.z = 0;
  group.add(cardMesh);

  // Accent edge (initially invisible)
  const borderWidth = 0.04;
  const edgeGeometry = new EdgesGeometry(new PlaneGeometry(2 + borderWidth, 1.25 + borderWidth));
  const lineMaterial = new LineBasicMaterial({
    color: accentColor,
    transparent: true,
    opacity: 0,
    linewidth: 2
  });
  const edgeLine = new Line(edgeGeometry, lineMaterial);
  edgeLine.position.z = 0.01; // slightly in front
  group.add(edgeLine);

  // Hover state
  let hovered = false;
  let pressed = false;

  // Hover lift animation
  const liftTimeline = gsap.timeline({ paused: true });
  liftTimeline
    .to(group.position, { y: 0.15, duration: 0.3, ease: 'power2.out' }, 0)
    .to(edgeLine.material, { opacity: 1, duration: 0.2, ease: 'power1.out' }, 0);

  const unLiftTimeline = gsap.timeline({ paused: true });
  unLiftTimeline
    .to(group.position, { y: 0, duration: 0.3, ease: 'power2.out' }, 0)
    .to(edgeLine.material, { opacity: 0, duration: 0.2, ease: 'power1.out' }, 0);

  // Press-down animation
  const pressTimeline = gsap.timeline({ paused: true });
  pressTimeline.to(cardMesh.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(1.7)' }, 0);

  const releaseTimeline = gsap.timeline({ paused: true });
  releaseTimeline.to(cardMesh.scale, { x: 1, y: 1, duration: 0.3, ease: 'power4.out' }, 0);

  // Event handlers
  group.userData.handlers = {
    pointerover: (e) => {
      e.stopPropagation();
      hovered = true;
      unLiftTimeline.pause(0).progress(0);
      liftTimeline.play();
    },
    pointerout: (e) => {
      e.stopPropagation();
      hovered = false;
      if (!pressed) {
        liftTimeline.pause(0).progress(0);
        unLiftTimeline.play();
      }
    },
    pointerdown: (e) => {
      e.stopPropagation();
      pressed = true;
      releaseTimeline.pause(0).progress(0);
      pressTimeline.play();
    },
    pointerup: (e) => {
      e.stopPropagation();
      if (pressed) {
        pressed = false;
        pressTimeline.pause(0).progress(0);
        releaseTimeline.play();
        ctx.emit('hub-journal.select', { source: 'quote-panel' });
        if (!hovered) {
          liftTimeline.pause(0).progress(0);
          unLiftTimeline.play();
        }
      }
    }
  };

  // Apply cinematic primitive: parallax-scroll
  let primitiveCleanup = () => {};
  if (config.cinematicPrimitives) {
    const parallaxPrim = config.cinematicPrimitives.find(p => p.name === 'parallax-scroll');
    if (parallaxPrim) {
      const res = ctx.primitives['parallax-scroll'](group, parallaxPrim.params || { intensity: 0.25 });
      primitiveCleanup = res.cleanup;
    }
  }

  // Cleanup
  group.userData.cleanup = () => {
    liftTimeline.kill();
    unLiftTimeline.kill();
    pressTimeline.kill();
    releaseTimeline.kill();
    primitiveCleanup();
    cardGeometry.dispose();
    cardMaterial.dispose();
    edgeGeometry.dispose();
    lineMaterial.dispose();
    // Cleanup gsap timelines that might be pending
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(cardMesh.scale);
    gsap.killTweensOf(edgeLine.material);
    if (texture) texture.dispose();
  };

  return group;
}
